{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "postpartum-return-12wk",
    "name": "12-Week Postpartum Return to Movement",
    "description": "A progressive 12-week home programme for a 33-year-old, four weeks post uncomplicated C-section, cleared for light activity only. Weeks 1–2 honour the OB restriction (walking, diaphragmatic breathing, pelvic floor only). Weeks 3–4 add gentle mobility and supported core reconnection after the six-week check. Weeks 5–8 introduce bodyweight strength. Weeks 9–12 build functional capacity. No abdominal loading, no heavy lifting, no high-impact until explicitly cleared.",
    "type": "hybrid",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "fitness-ai",
      "tags": [
        "postpartum",
        "c-section",
        "return-to-exercise",
        "pelvic-floor",
        "home",
        "no-equipment"
      ],
      "difficulty": "beginner",
      "estimated_duration_days": 84,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-pelvic-floor",
        "type": "primary",
        "category": "rehabilitation",
        "name": "Restore pelvic floor and deep core function",
        "description": "Re-establish neuromuscular connection with the pelvic floor and transverse abdominis before any loaded movement.",
        "milestones": [
          {
            "id": "ms-pf-awareness",
            "name": "Can perform 10 pelvic floor contractions without breath-holding",
            "target_value": 10,
            "reward_points": 50
          },
          {
            "id": "ms-pf-endurance",
            "name": "Can hold a pelvic floor contraction for 10 seconds x 10 reps",
            "target_value": 10,
            "reward_points": 100
          }
        ]
      },
      {
        "id": "goal-mobility",
        "type": "primary",
        "category": "mobility",
        "name": "Restore full pain-free hip and thoracic mobility",
        "milestones": [
          {
            "id": "ms-hip-mob",
            "name": "Pain-free full hip flexion and extension in all planes",
            "reward_points": 75
          }
        ]
      },
      {
        "id": "goal-strength",
        "type": "secondary",
        "category": "strength",
        "name": "Build foundational lower-body and posterior-chain strength",
        "description": "Progress to bodyweight squats, glute bridges, and hip hinges by week 8.",
        "milestones": [
          {
            "id": "ms-glute-bridge",
            "name": "3 sets of 15 glute bridges with full pelvic control",
            "target_value": 15,
            "reward_points": 100
          },
          {
            "id": "ms-squat",
            "name": "3 sets of 12 bodyweight squats pain-free",
            "target_value": 12,
            "reward_points": 150
          }
        ]
      },
      {
        "id": "goal-cardio",
        "type": "secondary",
        "category": "cardiovascular",
        "name": "Rebuild aerobic base through progressive walking",
        "target": {
          "metric": "continuous_walk_minutes",
          "target_value": 30,
          "unit": "minutes",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "ms-walk-15",
            "name": "Comfortable 15-minute continuous walk",
            "target_value": 15,
            "reward_points": 50
          },
          {
            "id": "ms-walk-30",
            "name": "Comfortable 30-minute continuous walk",
            "target_value": 30,
            "reward_points": 100
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 50,
      "fitness_level": ["beginner", "returning"],
      "equipment": [
        {
          "id": "eq-yoga-mat",
          "name": "Yoga mat",
          "required": true
        }
      ],
      "contraindications": [
        {
          "condition": "acog:pregnancy_t2",
          "severity": "high",
          "action": "require_clearance",
          "affected_activities": []
        },
        {
          "condition": "icd10:O82",
          "severity": "high",
          "action": "modify",
          "affected_activities": [
            "any_abdominal_loading",
            "any_high_impact",
            "any_heavy_lifting"
          ]
        },
        {
          "condition": "diastasis_recti",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "any_abdominal_loading"
          ]
        },
        {
          "condition": "pelvic_organ_prolapse",
          "severity": "high",
          "action": "require_clearance",
          "affected_activities": [
            "any_high_impact",
            "any_loaded_squat"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 5,
        "min_minutes_per_day": 15,
        "max_minutes_per_day": 45
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "pain_level",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Pain or discomfort level today (0 = none, 10 = severe)"
        },
        {
          "id": "energy_level",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Energy level today (1–10)"
        },
        {
          "id": "sleep_hours",
          "type": "number",
          "source": "wellness.sleep_hours_last_night",
          "label": "Hours of sleep last night"
        }
      ],
      "rules": [
        {
          "id": "rule-pain-skip",
          "condition": {
            "field": "pain_level",
            "op": "gte",
            "value": 5
          },
          "actions": [
            {
              "type": "substitute",
              "scope": "day",
              "replacement": "rest"
            }
          ]
        },
        {
          "id": "rule-low-energy",
          "condition": {
            "field": "energy_level",
            "op": "lte",
            "value": 3
          },
          "actions": [
            {
              "type": "reduce_volume",
              "scope": "day",
              "factor": 0.5
            }
          ]
        }
      ]
    },
    "athlete_thresholds": {
      "body_weight_kg": 65
    },
    "phases": [
